$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('SelectedMemberInfoSpy'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$module=$assembly.DefineDynamicModule('main');$builder=$module.DefineType('SelectedMemberInfoSpy',[Reflection.TypeAttributes]::Public,[Reflection.MemberInfo]);$null=$builder.DefineDefaultConstructor([Reflection.MethodAttributes]::Public);$calls=$builder.DefineField('Calls',[int],[Reflection.FieldAttributes]::Public)
foreach($base in [Reflection.MemberInfo].GetMethods([Reflection.BindingFlags]'Public,Instance')){if(-not $base.IsAbstract){continue};$parameters=[type[]]@($base.GetParameters()|ForEach-Object ParameterType);$method=$builder.DefineMethod($base.Name,[Reflection.MethodAttributes]'Public,Virtual,HideBySig',$base.ReturnType,$parameters);$il=$method.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$calls);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Add);$il.Emit([Reflection.Emit.OpCodes]::Stfld,$calls);$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'metadata getter');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$builder.DefineMethodOverride($method,$base)};$spyType=$builder.CreateType();$a=[Activator]::CreateInstance($spyType);$b=[Activator]::CreateInstance($spyType);$definition=[object].Assembly.GetType('System.Nullable`1');
$list=[object].Assembly.GetType('System.Collections.Generic.List`1');$listS=$list.MakeGenericType([type[]]@([string]));$nullable=$definition.MakeGenericType([type[]]@([int]));$objects=@{A=$a;A2=$a;B=$b;I=[int];Array=[int[]];C=$nullable;P=$definition.GetGenericArguments()[0];ListD=$list;ListS=$listS;Dispose=[IDisposable].GetMethod('Dispose');Compare=[IComparable].GetMethod('CompareTo');Format=[IFormatProvider].GetMethod('GetFormat');Chars=[string].GetDefaultMembers()[0];ListItem=$listS.GetDefaultMembers()[0];NullableArray=$nullable.MakeArrayType()};$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$getter=[Reflection.MemberInfo].GetProperty('IsCollectible').GetMethod;$rows=[Collections.Generic.List[object]]::new()
foreach($key in $plan.keys){$value=$objects[$key];$first=[bool]$getter.Invoke($value,[object[]]@());$second=[bool]$getter.Invoke($value,[object[]]@());$otherCalls=$null;if($key -in @('A','A2','B')){$otherCalls=$value.Calls};$rows.Add([ordered]@{key=$key;collectible=$first;repeat=$second;otherCalls=$otherCalls})}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();rows=$rows.ToArray();getterCallsA=$a.Calls;getterCallsB=$b.Calls;qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS MemberInfo collectibility: 30 getter calls'
